from collections import Counter

def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def majority_color(grid, exclude=()):
    """The most common color excluding the given ones."""
    c = Counter(v for row in grid for v in row if v not in exclude)
    return c.most_common(1)[0][0]

def rare_color(grid, exclude=()):
    """The least common color excluding the given ones."""
    c = Counter(v for row in grid for v in row if v not in exclude)
    return min(c, key=c.get)

def bbox(grid):
    """(top, left, bottom, right) of the non-background cells; None if none."""
    bg = background(grid)
    cells = [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v != bg]
    if not cells:
        return None
    return (min(i for i, _ in cells), min(j for _, j in cells),
            max(i for i, _ in cells), max(j for _, j in cells))

def full_rows(grid, color):
    """Indices of rows that are entirely the given color."""
    return [i for i, row in enumerate(grid) if all(v == color for v in row)]

def full_cols(grid, color):
    """Indices of columns that are entirely the given color."""
    return [j for j in range(len(grid[0])) if all(row[j] == color for row in grid)]

def cells_of(grid, color):
    """Set of (row, col) of all cells of the given color."""
    return {(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color}

def draw_line(out, idx, color, orient):
    """Draw a full row ('h') or column ('v') line at the given index on grid out."""
    if orient == 'h':
        out[idx] = [color] * len(out[idx])
    else:
        for row in out:
            row[idx] = color

def blit_color(out, cells, dr, dc, color):
    """Paint each (r, c) of cells shifted by (dr, dc) with color."""
    for r, c in cells:
        out[r + dr][c + dc] = color

def hmirror(grid):
    """The grid mirrored left to right."""
    return [row[::-1] for row in grid]

def vflip(grid):
    """The grid flipped top to bottom."""
    return grid[::-1]

def hstack(a, b):
    """The two grids side by side; they must have the same height."""
    return [ra + rb for ra, rb in zip(a, b)]

def vstack(*grids):
    """The grids stacked top to bottom; they must have the same width."""
    return [row for g in grids for row in g]

def draw_border(grid, color):
    """Color every background cell on the border of the non-background cells' bounding box, keeping marked cells."""
    bg = background(grid)
    t, l, b, r = bbox(grid)
    out = [row[:] for row in grid]
    for j in range(l, r + 1):
        for i in (t, b):
            if out[i][j] == bg:
                out[i][j] = color
    for i in range(t, b + 1):
        for j in (l, r):
            if out[i][j] == bg:
                out[i][j] = color
    return out

def fill_line_gaps(grid, color):
    """Fill background cells sandwiched between two marked (non-background, non-color) cells in their row or column."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(1, w - 1):
            a, m, c = out[i][j-1], out[i][j], out[i][j+1]
            if m == bg and a != bg and a != color and c != bg and c != color:
                out[i][j] = color
    for j in range(w):
        for i in range(1, h - 1):
            a, m, c = out[i-1][j], out[i][j], out[i+1][j]
            if m == bg and a != bg and a != color and c != bg and c != color:
                out[i][j] = color
    return out

def fill_h_gaps(grid, color=2):
    """Fill background cells that lie between a non-background cell on their left and one on their right in the same row."""
    bg = background(grid)
    out = [row[:] for row in grid]
    for row in out:
        for j, v in enumerate(row):
            if v == bg and any(x != bg for x in row[:j]) and any(x != bg for x in row[j+1:]):
                row[j] = color
    return out

def fall_down(grid):
    """The whole non-background content shifted down one row; whatever falls off the bottom is lost."""
    bg = background(grid)
    return [[bg] * len(grid[0])] + [row[:] for row in grid[:-1]]

def downsample_majority(grid, factor=None):
    """Each factor x factor block as its most common color that is neither 0 nor the background, or 0 if it has none; factor defaults to side // number of distinct colors."""
    h, w = len(grid), len(grid[0])
    if factor is None:
        factor = h // len({v for row in grid for v in row})
    bg = background(grid)
    out = []
    for k in range(0, h, factor):
        row = []
        for j in range(0, w, factor):
            cnt = Counter(v for r in grid[k:k+factor] for v in r[j:j+factor] if v != 0 and v != bg)
            row.append(cnt.most_common(1)[0][0] if cnt else 0)
        out.append(row)
    return out


def fill_ring_interiors(grid, color=None):
    """Fill the inside of every closed rectangular ring (hollow rectangle) with the given color."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if seen[i][j] or out[i][j] == bg:
                continue
            c = out[i][j]
            comp = [(i, j)]
            stack = [(i, j)]
            seen[i][j] = True
            while stack:
                r, cc = stack.pop()
                for nr, nc in ((r+1,cc),(r-1,cc),(r,cc+1),(r,cc-1)):
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and out[nr][nc] == c:
                        seen[nr][nc] = True
                        comp.append((nr, nc))
                        stack.append((nr, nc))
            rs = [r for r, _ in comp]; cs = [c2 for _, c2 in comp]
            t, l, b, r2 = min(rs), min(cs), max(rs), max(cs)
            if len(comp) == 2 * (b - t + 1) + 2 * (r2 - l + 1) - 4 and b > t + 1 and r2 > l + 1:
                area = (b - t - 1) * (r2 - l - 1)
                fillc = color if color is not None else (2 if area % 2 == 0 else 7)
                for m in range(t + 1, b):
                    for n in range(l + 1, r2):
                        out[m][n] = fillc
    return out

def extend_diagonal_runs(grid):
    """Complete every diagonal run of two or more same-colored cells whose diagonal also holds a different color: extend it through background cells to the border or the next cell."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for dr, dc in ((1, 1), (1, -1)):
        seen = set()
        for i in range(h):
            for j in range(w):
                if (i, j) in seen:
                    continue
                c = grid[i][j]
                if c == bg:
                    continue
                run = [(i, j)]; seen.add((i, j))
                y, x = i + dr, j + dc
                while 0 <= y < h and 0 <= x < w and grid[y][x] == c:
                    run.append((y, x)); seen.add((y, x)); y += dr; x += dc
                if len(run) < 2:
                    continue
                # does this diagonal contain a color other than c?
                other = False
                y, x = run[0][0] - dr, run[0][1] - dc
                while 0 <= y < h and 0 <= x < w:
                    if grid[y][x] != bg and grid[y][x] != c:
                        other = True
                    y -= dr; x -= dc
                y, x = run[-1][0] + dr, run[-1][1] + dc
                while 0 <= y < h and 0 <= x < w:
                    if grid[y][x] != bg and grid[y][x] != c:
                        other = True
                    y += dr; x += dc
                if not other:
                    continue
                for sy, sx, uy, ux in ((run[-1][0], run[-1][1], dr, dc), (run[0][0], run[0][1], -dr, -dc)):
                    y, x = sy + uy, sx + ux
                    while 0 <= y < h and 0 <= x < w and grid[y][x] == bg:
                        out[y][x] = c; y += uy; x += ux
    return out

def line_runs(cells):
    """Group cells into two parallel runs of >=2 sharing a row or column; returns (runs, horiz) or (None, None)."""
    from collections import defaultdict
    byrow=defaultdict(list); bycol=defaultdict(list)
    for i,j in cells: byrow[i].append(j); bycol[j].append(i)
    rr={i:sorted(v) for i,v in byrow.items() if len(v)>=2}
    cc={j:sorted(v) for j,v in bycol.items() if len(v)>=2}
    if len(rr)==2 and len(cc)!=2:
        return [[(i,j) for j in rr[i]] for i in sorted(rr)], True
    if len(cc)==2 and len(rr)!=2:
        return [[(i,j) for i in cc[j]] for j in sorted(cc)], False
    return None, None

def paired_beam_fill(grid, junction=4):
    """Two parallel marker runs and seed cells: each seed beams toward its run's cell (seed becomes `junction`),
